const H = params.height;
const towerH = H * 0.74;
const hubY = H * 0.735;
const rotorR = H * 0.245;
const baseR = H * 0.032;
const topR = H * 0.018;
const white = { preset: 'metal', color: '#eef2f3', metalness: 0.18, roughness: 0.38 };
const bladeMat = { preset: 'plastic', color: '#f7f8f6', roughness: 0.32 };
const dark = { preset: 'metal', color: '#39434a', metalness: 0.65, roughness: 0.3 };
const accent = { preset: 'plastic', color: '#b8c2c8', roughness: 0.45 };
const towerProfile = [[0, 0], [baseR * 1.18, 0], [baseR * 1.18, H * 0.018], [baseR, H * 0.025], [topR, towerH], [0, towerH]];
api.add(api.lathe(towerProfile, 20), white);
api.add(api.cylinder(baseR * 1.35, baseR * 1.45, H * 0.018, 20).translate(0, H * 0.009, 0), accent);
const nacelleLength = H * 0.105;
const nacelle = api.capsule(H * 0.025, nacelleLength).rotate(90, 0, 0).scale(1, 0.82, 1).translate(0, hubY, -H * 0.027);
api.add(nacelle, white);
api.add(api.box(H * 0.038, H * 0.012, H * 0.047).translate(0, hubY - H * 0.021, -H * 0.025), accent);
api.add(api.cylinder(H * 0.006, H * 0.006, H * 0.018, 10).translate(0, hubY + H * 0.035, -H * 0.052), dark);
api.add(api.sphere(H * 0.008, 1).translate(0, hubY + H * 0.045, -H * 0.052), { preset: 'emissive', color: '#d94335', emissive: '#d94335', emissiveIntensity: 1.6 });
const hubZ = H * 0.036;
api.add(api.cylinder(H * 0.026, H * 0.033, H * 0.045, 16).rotate(90, 0, 0).translate(0, hubY, hubZ * 0.45), white);
api.add(api.sphere(H * 0.029, 2).scale(1, 1, 0.72).translate(0, hubY, hubZ), accent);
const root = rotorR * 0.105;
const bladeShape = [[-rotorR * 0.018, root], [rotorR * 0.028, root], [rotorR * 0.045, rotorR * 0.28], [rotorR * 0.022, rotorR * 0.68], [rotorR * 0.006, rotorR], [-rotorR * 0.009, rotorR * 0.98], [-rotorR * 0.014, rotorR * 0.55]];
for (let i = 0; i < 3; i++) {
  const angle = i * 120;
  const blade = api.extrude(bladeShape, H * 0.008).rotate(0, 0, angle).translate(0, hubY, hubZ + H * 0.008);
  api.add(blade, bladeMat);
  const a = angle * Math.PI / 180;
  const mid = root + (rotorR - root) * 0.48;
  api.collider({ kind: 'box', halfExtents: [rotorR * 0.026, (rotorR - root) * 0.48, H * 0.005], offset: [-Math.sin(a) * mid, hubY + Math.cos(a) * mid, hubZ + H * 0.008], rotation: [0, 0, angle] });
}
api.add(api.box(H * 0.018, H * 0.032, H * 0.003).translate(0, H * 0.085, baseR * 0.99), dark);
api.add(api.box(H * 0.011, H * 0.003, H * 0.0015).translate(0, H * 0.087, baseR * 1.045), accent);
api.collider({ kind: 'cylinder', radius: baseR * 1.18, halfHeight: towerH * 0.5, offset: [0, towerH * 0.5, 0] });
api.collider({ kind: 'box', halfExtents: [H * 0.027, H * 0.027, nacelleLength * 0.5], offset: [0, hubY, -H * 0.027] });
api.collider({ kind: 'sphere', radius: H * 0.034, offset: [0, hubY, hubZ] });
return api.build();
